    func visit(_ page: Int) {
        let node = pages[page]!
        tokens.append("(")
        if !node.leaf {
            visit(node.children[0])
        }
        for index in node.entries.indices {
            tokens.append(node.entries[index].display)
            if !node.leaf {
                visit(node.children[index + 1])
            }
        }
        tokens.append(")")
    }
